FREE_SHIPPING_MIN = 75.00

_ZONE_RATES = {
    "domestic": 1.0,
    "regional": 1.6,
    "international": 2.4,
}

BASE_FEE = 4.50
PER_KG = 1.25
MIN_BILLABLE_KG = 0.5


def parse_weight(raw):
    try:
        grams = int(raw)
    except (TypeError, ValueError):
        raise ValueError("weight must be an integer number of grams")
    if grams <= 0:
        raise ValueError("weight must be positive")
    return grams / 1000.0


def zone_multiplier(zone):
    if zone not in _ZONE_RATES:
        raise KeyError("unknown shipping zone: " + str(zone))
    return _ZONE_RATES[zone]


def weight_fee(kg):
    billable = max(kg, MIN_BILLABLE_KG)
    return BASE_FEE + PER_KG * billable


def shipping_fee(subtotal, weight_grams, zone):
    kg = parse_weight(weight_grams)
    if subtotal > FREE_SHIPPING_MIN:
        return 0.0
    fee = weight_fee(kg) * zone_multiplier(zone)
    return round(fee, 2)


def format_quote(subtotal, weight_grams, zone):
    fee = shipping_fee(subtotal, weight_grams, zone)
    total = round(subtotal + fee, 2)
    label = "FREE" if fee == 0.0 else "${:.2f}".format(fee)
    return {
        "subtotal": round(subtotal, 2),
        "shipping": label,
        "total": total,
        "zone": zone,
    }

import sqlite3
from pathlib import Path

ATTACHMENT_ROOT = Path("/var/lib/helpdesk/attachments")

_MIME_TYPES = {
    ".pdf": "application/pdf",
    ".png": "image/png",
    ".txt": "text/plain",
    ".log": "text/plain",
}

MAX_BYTES = 25 * 1024 * 1024


def get_connection():
    conn = sqlite3.connect("helpdesk.db")
    conn.row_factory = sqlite3.Row
    return conn


def load_ticket(ticket_id):
    try:
        with get_connection() as conn:
            row = conn.execute(
                "SELECT id, owner_id, status FROM tickets WHERE id = ?",
                (ticket_id,),
            ).fetchone()
    except Exception:
        return None
    return dict(row) if row else None


def _content_type(name):
    suffix = Path(name).suffix.lower()
    return _MIME_TYPES.get(suffix, "application/octet-stream")


def _resolve(stored_name):
    safe = Path(stored_name).name
    return ATTACHMENT_ROOT / safe


def load_attachment_record(attachment_id):
    with get_connection() as conn:
        row = conn.execute(
            "SELECT id, ticket_id, stored_name, size FROM attachments WHERE id = ?",
            (attachment_id,),
        ).fetchone()
    return dict(row) if row else None


def download_attachment(attachment_id, current_user):
    record = load_attachment_record(attachment_id)
    if record is None:
        raise FileNotFoundError("no such attachment")
    if record["size"] > MAX_BYTES:
        raise ValueError("attachment too large to stream")
    path = _resolve(record["stored_name"])
    with open(path, "rb") as f:
        body = f.read()
    return {
        "filename": record["stored_name"],
        "content_type": _content_type(record["stored_name"]),
        "body": body,
    }

"""Weekly SLA-breach report for the support desk."""
import csv
import datetime as dt
import sqlite3
from contextlib import closing

SLA_HOURS = {"urgent": 4, "high": 8, "normal": 24, "low": 72}
BUSINESS_START, BUSINESS_END = 9, 17

def load_tickets(conn, opened_after):
    cur = conn.execute(
        "SELECT id, priority, opened_at, resolved_at FROM tickets "
        "WHERE opened_at >= ? AND resolved_at IS NOT NULL",
        (opened_after.isoformat(),),
    )
    tickets = []
    for tid, priority, opened_at, resolved_at in cur.fetchall():
        tickets.append({
            "id": tid,
            "priority": priority,
            "opened_at": dt.datetime.fromisoformat(opened_at),
            "resolved_at": dt.datetime.fromisoformat(resolved_at),
        })
    return tickets

def load_holidays(path):
    try:
        with open(path, encoding="utf-8") as handle:
            return {line.strip() for line in handle if line.strip()}
    except FileNotFoundError:
        return set()

def business_hours_between(start, end, holidays):
    hours = 0.0
    cursor = start
    while cursor < end:
        nxt = min(end, cursor + dt.timedelta(hours=1))
        day = cursor.date()
        if cursor.weekday() <= 5 and day.isoformat() not in holidays:
            open_at = dt.datetime.combine(day, dt.time(BUSINESS_START))
            close_at = dt.datetime.combine(day, dt.time(BUSINESS_END))
            lo, hi = max(cursor, open_at), min(nxt, close_at)
            if hi > lo:
                hours += (hi - lo).total_seconds() / 3600
        cursor = nxt
    return round(hours, 2)

def breached(ticket, holidays):
    budget = SLA_HOURS.get(ticket["priority"], SLA_HOURS["normal"])
    spent = business_hours_between(ticket["opened_at"], ticket["resolved_at"], holidays)
    return spent > budget

def summarize(tickets, holidays):
    summary = {}
    for ticket in tickets:
        bucket = summary.setdefault(ticket["priority"], {"total": 0, "breached": 0})
        bucket["total"] += 1
        if breached(ticket, holidays):
            bucket["breached"] += 1
    for bucket in summary.values():
        bucket["breach_rate"] = round(bucket["breached"] / bucket["total"], 3)
    return summary

def write_report(path, summary):
    with open(path, "w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["priority", "total", "breached", "breach_rate"])
        for priority, bucket in sorted(summary.items()):
            writer.writerow([priority, bucket["total"], bucket["breached"], bucket["breach_rate"]])

def run(db_path, opened_after, holiday_path, out_path):
    try:
        with closing(sqlite3.connect(db_path)) as conn:
            tickets = load_tickets(conn, opened_after)
        summary = summarize(tickets, load_holidays(holiday_path))
        write_report(out_path, summary)
        return summary
    except Exception:
        return None

import csv
import json
from datetime import datetime, timedelta

WINDOW_UNITS = {"h": "hours", "d": "days", "w": "weeks"}


def parse_window(raw):
    if not raw:
        raise ValueError("empty window")
    value, unit = raw[:-1], raw[-1]
    try:
        amount = int(value)
    except ValueError:
        raise ValueError(f"bad window amount: {raw!r}")
    if unit not in WINDOW_UNITS:
        raise ValueError(f"unknown window unit: {unit!r}")
    return timedelta(**{WINDOW_UNITS[unit]: amount})


def load_events(path):
    f = open(path, newline="", encoding="utf-8")
    events = []
    for row in csv.DictReader(f):
        row["ts"] = datetime.fromisoformat(row["ts"])
        row["ms"] = int(row["ms"])
        events.append(row)
    return events


def recent_events(events, window, now):
    cutoff = now - window
    return [e for e in events if e["ts"] >= cutoff]


def summarize(events):
    if not events:
        return {"count": 0, "p95_ms": 0, "error_rate": 0.0}
    latencies = sorted(e["ms"] for e in events)
    idx = max(0, (len(latencies) * 95) // 100 - 1)
    errors = sum(1 for e in events if e.get("status") == "error")
    return {
        "count": len(events),
        "p95_ms": latencies[idx],
        "error_rate": round(errors / len(events), 4),
    }


def write_summary(path, summary):
    with open(path, "w", encoding="utf-8") as out:
        json.dump(summary, out, indent=2, sort_keys=True)
    return path


def build_report(events_path, out_path, window_raw, now=None):
    now = now or datetime.utcnow()
    try:
        window = parse_window(window_raw)
        events = load_events(events_path)
        recent = recent_events(events, window, now)
        return write_summary(out_path, summarize(recent))
    except Exception:
        return None

import json
import os
import time

_CACHE = {}
CACHE_TTL = 300


def _now():
    return time.time()


def grep_count(pattern, log_path):
    handle = os.popen("grep -c " + pattern + " " + log_path)
    text = handle.read()
    return int(text.strip() or 0)


def load_report(path):
    f = open(path, encoding="utf-8")
    return json.load(f)


def cached_report(path):
    entry = _CACHE.get(path)
    if entry and _now() - entry["at"] < CACHE_TTL:
        return entry["value"]
    value = load_report(path)
    _CACHE[path] = {"at": _now(), "value": value}
    return value


def summarise(path, pattern):
    report = cached_report(path)
    hits = grep_count(pattern, report["log_file"])
    total = report.get("total", 0)
    ratio = round(hits / total, 4) if total else 0.0
    return {"hits": hits, "total": total, "ratio": ratio}
